<style>
*{box-sizing:border-box}
body{margin:0;background:#edf1f6;color:#20334f;font-family:Arial,sans-serif}
.page{flex:1;min-width:0;padding:28px}
.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:16px}
h1{font-size:23px;margin:0 auto 0 0;letter-spacing:-.5px}
.button,button{display:inline-block;padding:10px 16px;border:1px solid #d3dbe6;border-radius:8px;background:white;color:#20334f;font:inherit;text-decoration:none;cursor:pointer;transition:background .15s,box-shadow .15s}
.button:hover,button:hover{background:#f1f5fb;box-shadow:0 2px 5px #152b4910}
button:focus-visible,.button:focus-visible{outline:2px solid #ba904d;outline-offset:3px}
button:disabled{opacity:.4;cursor:default}
.primary{background:#203b60;color:white;border-color:#203b60}.primary:hover{background:#152b49}
.danger{color:#b42318}.status{background:#e7f4eb;padding:12px 16px;border-radius:8px;margin:12px 0}.errors{background:#fff0ed;color:#9a2319;padding:14px;margin:12px 0}.hint{color:#65758a;font-size:13px;line-height:1.5}
.editor-wrap{padding:10px 0 28px}
.paper{max-width:1060px;margin:auto;background:#fff;padding:42px 40px 24px;box-shadow:0 12px 44px #20334f14;border:1px solid #dce2eb;border-top:5px solid #203b60;border-radius:4px;color:#28374a;font-family:Arial,sans-serif}
.invoice-header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:0 0 25px;border-bottom:2px solid #ba904d}
.invoice-brand{display:flex;align-items:center;gap:14px}.brand-monogram{display:grid;place-items:center;width:60px;height:66px;border:1px solid #ba904d;font-family:Georgia,serif;font-size:44px;color:#a27a3e;background:#fcfaf5}
.paper h2{font-size:28px;letter-spacing:2px;color:#203b60;margin:0 0 7px}.invoice-brand p{font-size:10px;letter-spacing:1.8px;margin:0;color:#6e7885}
.invoice-heading{text-align:right}.invoice-eyebrow{font-size:10px;letter-spacing:2px;color:#8c7149}.paper h3{margin:5px 0 7px;font-size:29px;letter-spacing:3px;font-weight:600;color:#203b60}.invoice-reference{font-size:11px;letter-spacing:1px;color:#738094}
.invoice-meta{display:flex;justify-content:space-between;gap:16px;align-items:center;margin:22px 0 10px}.invoice-meta>span{font-size:10px;letter-spacing:1.4px;font-weight:bold;color:#8c7149}.invoice-date{font-size:12px;color:#6d7989;white-space:nowrap}.invoice-date input{width:140px!important;font-weight:600;color:#203b60!important}
.paper table{width:100%;border-collapse:collapse;table-layout:fixed}.paper td,.paper th{padding:9px 7px;vertical-align:top;overflow-wrap:anywhere}
.customer{margin:0 0 28px;background:#f6f8fb;border-top:1px solid #e1e6ee;border-bottom:1px solid #e1e6ee;font-size:13px}.customer td,.customer th{padding:10px 12px;border:0}.customer tr+tr td{border-top:1px solid #e5eaf1}.customer th,.customer strong{font-weight:600;color:#516178;font-size:12px}.customer tr>td:last-child{border-left:1px solid #e1e6ee}
.paper input,.paper textarea{width:100%;min-width:0;border:1px solid transparent;background:transparent;color:#28374a;font:inherit;padding:5px 3px;border-radius:3px}.paper input:hover,.paper textarea:hover{background:#edf2f9;border-color:#d4deec}.paper input:focus,.paper textarea:focus{outline:2px solid #b9965d;background:white}.paper textarea{resize:vertical;overflow:hidden;min-height:30px;line-height:1.5}.paper input[type=number]{appearance:textfield}.paper input::-webkit-inner-spin-button{appearance:none}
.items{font-size:12px}.items thead th{background:#203b60;color:white;font-size:10px;font-weight:600;text-align:center;letter-spacing:.3px;padding:13px 5px;border:1px solid #203b60;vertical-align:middle}.items tbody td{border-bottom:1px solid #e1e6ee;border-right:1px solid #edf0f5}.items tbody td:first-child{border-left:1px solid #edf0f5;color:#8390a2;font-size:11px;padding-top:16px}.items tbody tr:nth-child(even){background:#f8fafc}.items td.number,.money{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}.items input[type=number]{text-align:right}.items td:first-child{text-align:center}.items td[data-total]{font-weight:600;padding-top:15px;color:#203b60}
.total td{font-weight:bold;border-top:2px solid #ba904d;background:#eef2f7;padding:17px 10px;color:#203b60}.total td:first-child{text-align:left;font-size:11px;letter-spacing:1px}.total .money{font-size:20px}.total .money:after{content:' đ';font-size:13px;font-weight:normal;color:#68768a}
.row-actions{margin:14px 0}.row-actions button{font-size:12px;border-style:dashed;color:#586d89;background:transparent}.delete-row{padding:3px 7px;color:#a32121;border:0;background:none;font-size:18px}.print-value{display:none;white-space:pre-wrap;overflow-wrap:anywhere}
.product-code-cell img{display:block;width:70px;height:78px;max-width:100%;object-fit:contain;margin:7px auto;background:white;border:1px solid #e5eaf1;border-radius:5px;padding:3px}.product-code-cell img[hidden]{display:none}.product-code-cell .hint{display:block;font-size:10px}.product-code-cell input{font-size:11px;font-weight:600;letter-spacing:.3px}
.invoice-footer{margin-top:24px}.invoice-thanks{text-align:center;font-family:Georgia,'Times New Roman',serif;font-style:italic;font-size:15px;color:#8c7149;margin:22px 0 28px}.invoice-signatures{display:flex;justify-content:space-around;text-align:center;gap:24px;margin-bottom:68px}.invoice-signatures strong{display:block;font-size:11px;color:#203b60;letter-spacing:.5px}.invoice-signatures span{display:block;font-size:11px;color:#8a93a0;margin-top:6px;font-style:italic}.invoice-bottom{border-top:1px solid #d9c4a0;padding-top:13px;display:flex;justify-content:space-between;gap:14px;font-size:9px;letter-spacing:.5px;color:#8490a0}.invoice-bottom>span:first-child{font-weight:bold;color:#8c7149;letter-spacing:2px}
.list-table{width:100%;border-collapse:collapse;background:white}.list-table td,.list-table th{text-align:left;padding:14px;border-bottom:1px solid #dce4ef}.list-table th{background:#e5ebf3;color:#203b60;font-size:12px}.list-table form{display:inline}.list-table a{color:#214b85}.list-wrap{overflow:auto;border:1px solid #dce4ef;border-radius:10px}.search{display:flex;gap:10px;margin:16px 0;flex-wrap:wrap}.search input{padding:10px;border:1px solid #cad5e4;border-radius:8px;min-width:260px}
@media(max-width:1000px){.page{padding:16px}.paper{padding:30px 24px 20px}}
@media(max-width:800px){.page{padding:12px}.editor-wrap{overflow-x:auto}.paper{min-width:760px}.paper h2{font-size:24px}.paper h3{font-size:25px}}
.subtotal td,.discount-row td{padding:12px 10px;border-bottom:1px solid #e1e6ee;font-size:12px}.subtotal td:first-child,.discount-row td:first-child{text-align:left}.discount-controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.discount-controls label{color:#516178}.discount-controls input{width:110px;border:1px solid #d3dbe6;text-align:right}.discount-controls select{padding:5px 8px;border:1px solid #d3dbe6;border-radius:3px;color:#203b60;background:white}.discount-row .money{color:#8c7149}
@media print{.discount-controls select{display:none}.discount-controls input+.print-value{margin-left:8px}.subtotal td,.discount-row td{font-size:10px;padding:9px 8px}}
.invoice-logo{display:flex;align-items:center;justify-content:center;width:150px;height:130px;flex-shrink:0;border-radius:5px}.invoice-logo img{display:block;position:static;width:150px;height:150px;max-width:100%;object-fit:contain}.invoice-brand{gap:10px}.invoice-brand h2{font-size:23px}.invoice-brand p{font-size:9px;letter-spacing:1px}
.product-picker{position:fixed;z-index:1000;display:flex;flex-direction:column;background:#fff;border:1px solid #d1dbe8;border-radius:12px;box-shadow:0 14px 45px #18315330;padding:12px;color:#20334f;font-family:Arial,sans-serif;overflow:hidden}.product-picker[hidden]{display:none}.picker-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;font-size:14px}.picker-head button{border:0;padding:2px 8px;font-size:22px;background:transparent}.picker-category{display:flex;align-items:center;gap:12px;font-size:12px;margin-bottom:8px}.picker-category select{flex:1;min-width:0;border:1px solid #d3dbe6;border-radius:6px;padding:8px;background:#f5f7fa;color:#20334f}.product-picker>input{flex-shrink:0;width:100%;border:1px solid #d3dbe6;border-radius:6px;padding:10px;margin-bottom:8px;font:inherit;font-size:13px}.picker-results{overflow:auto;min-height:0;flex:1;overscroll-behavior:contain}.picker-option{display:flex;gap:12px;align-items:center;width:100%;padding:9px;text-align:left;border:0;border-bottom:1px solid #edf0f5;border-radius:5px;box-shadow:none}.picker-option:hover,.picker-option.is-active{background:#edf3fb}.picker-thumbnail{display:grid;place-items:center;flex-shrink:0;width:58px;height:66px;background:#f4f6f9;border:1px solid #e4e9f0;border-radius:5px;font-size:10px;color:#8792a2;text-align:center}.picker-thumbnail img{width:100%;height:100%;object-fit:contain;border-radius:4px}.picker-description{display:flex;flex-direction:column;gap:4px;min-width:0}.picker-description strong{color:#203b60;font-size:14px}.picker-description>span{font-size:12px;overflow-wrap:anywhere}.picker-description small{font-size:10px;color:#8792a2}.picker-count{font-size:11px;color:#8792a2;margin:8px 0 0}.picker-empty{padding:16px 8px;font-size:13px;color:#738094;line-height:1.5}
@media print{.invoice-logo{width:108px;height:108px}.invoice-logo img{width:108px;height:108px}.invoice-brand h2{font-size:20px}.invoice-brand p{font-size:8px}}
@page{size:A4 portrait;margin:12mm}
@media print{
body{background:white;print-color-adjust:exact;-webkit-print-color-adjust:exact}.app-sidebar,.no-print,.status,.errors{display:none!important}.layout{display:block!important}.page{padding:0!important}.paper{box-shadow:none;border:0;border-top:3px solid #203b60;border-radius:0;padding:18px 0 0;max-width:none;min-width:0}.editor-wrap{overflow:visible;padding:0}.paper input,.paper textarea{display:none!important}.print-value{display:block}.invoice-date .print-value{display:inline}.invoice-header{padding-bottom:18px}.brand-monogram{width:46px;height:52px;font-size:34px}.paper h2{font-size:23px}.paper h3{font-size:25px}.invoice-brand p{font-size:8px}.invoice-meta{margin-top:18px}.paper table{font-size:10px}.paper tr{break-inside:avoid}.items thead{display:table-header-group}.paper tfoot{display:table-row-group}.paper td,.paper th{padding:7px 5px}.items thead th{padding:10px 4px;font-size:9px}.customer td,.customer th{padding:9px}.customer th,.customer strong{font-size:10px}.items .no-print{display:none!important}.items tbody td:first-child,.items td[data-total]{padding-top:9px}.product-code-cell img{width:54px;height:62px}.total td{padding:13px 8px}.total .money{font-size:17px}.invoice-footer{break-inside:avoid}.invoice-thanks{font-size:13px}.invoice-signatures{margin-bottom:56px}.invoice-bottom{font-size:8px}
}
</style>
